using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using LogicLegends.Trees;
using UnityEditor;
using UnityEngine;

namespace LogicLegends.OpenArchive.Topics.Editor
{
    public static class ArchiveTreeChecks
    {
        [Serializable]sealed class CheckResult{public string name;public bool passed;}
        [Serializable]sealed class Report{public bool passed;public string scope="Current solo variants and native Editor Book/Hand/diagram/edge/number buttons. Shared session and real movement-lock restrictions exercised. Deadlines aged; physical Android separate.";public List<CheckResult> checks=new List<CheckResult>();public List<string> errors=new List<string>();}
        static Report report;static ArchiveTopicSession session;static ArchiveTopicStation station;static ArchiveTreeUI ui;static bool active,oldHunting;static double next;static GameObject restriction;static readonly Stack<IEnumerator> stack=new Stack<IEnumerator>();
        public static string Status{get;private set;}="Idle";
        static ArchiveStationState State=>session.State.stations[9];
        static void Check(bool ok,string name){report.checks.Add(new CheckResult{name=name,passed=ok});if(!ok)throw new InvalidOperationException(name);}
        public static string ValidateVariants(){var c=AssetDatabase.LoadAssetAtPath<ArchiveTopicCatalog>(ArchiveTopicSetup.Folder+"/Archive_Topic_Catalog.asset");var r=new Report();int count=0,spanningAnswers=0;Action<bool,string> test=(ok,name)=>{r.checks.Add(new CheckResult{name=name,passed=ok});if(!ok)r.errors.Add(name);};
            try{test(c.trees==AssetDatabase.LoadAssetAtPath<TreeChallengeCatalog>("Assets/Prefabs/Trees/TreeChallenges.asset"),"Same original solo tree catalog, with no copied question bank");for(int group=0;group<5;group++)for(int entry=0;entry<10;entry++){int round=group;var data=c.trees.variantSets[group].variants[entry];int seed=Enumerable.Range(1,4096).First(n=>ReferenceEquals(ArchiveTopicQuestions.Build(c,9,round,n).tree,data));var q=ArchiveTopicQuestions.Build(c,9,group,seed);var good=ArchiveTopicChecks.Solution(q);string key="Challenge "+(group+1)+" / variant "+(entry+1);count++;test(q.prompt==data.objective&&q.nodeIds.SequenceEqual(data.nodes.Select(n=>n.id)),key+" preserves source objective, IDs, topology and lesson");test(q.nodes.All(p=>Mathf.Abs(p.x)<=4.81f&&Mathf.Abs(p.y)<=4.81f),key+" fits inside the reserved arena");test(ArchiveTopicQuestions.Validate(q,good,out _),key+" accepts the original correct answer");var malformed=ArchiveTopicChecks.Solution(q);malformed.links.Add(9999);test(!ArchiveTopicQuestions.Validate(q,malformed,out _),key+" rejects invalid endpoint IDs without throwing");malformed=ArchiveTopicChecks.Solution(q);if(malformed.links.Count>0)malformed.links.Add(malformed.links[0]);else malformed.links.Add(0);test(!ArchiveTopicQuestions.Validate(q,malformed,out _),key+" rejects duplicate and self connections");
                if(data.Editable){var s=new ArchiveStationState{phase=1};ArchiveTopicQuestions.Prepare(q,s);foreach(int link in s.links.Except(good.links).ToArray()){bool ok=ArchiveTreeRules.Edit(q,s,link%100,link/100,true,out _);test(ok,key+" removes an incorrect branch in reverse endpoint order");}foreach(int link in good.links.Except(s.links).ToArray())test(ArchiveTreeRules.Edit(q,s,link/100,link%100,false,out _),key+" builds a required branch using the original edit guards");test(ArchiveTopicQuestions.Validate(q,s,out _),key+" solves through edits rather than replacing the entire graph");var clone=JsonUtility.FromJson<ArchiveStationState>(JsonUtility.ToJson(s));test(ArchiveTopicQuestions.Validate(q,clone,out _),key+" retains its meaning after snapshot restoration");int one=s.links[0];test(!ArchiveTreeRules.CanEdit(q,s,one/100,one%100,false,out _),key+" rejects a duplicate branch");if(data.Directed){int root=Array.IndexOf(q.nodeIds,data.root);test(!ArchiveTreeRules.CanEdit(q,s,(root+1)%q.nodes.Length,root,false,out _),key+" prevents an incoming parent for the root");}}
                if(data.type==TreeChallengeType.Identify)for(int i=0;i<q.nodeIds.Length;i++){var pick=ArchiveTopicChecks.Solution(q);pick.selection=i;bool expected=TreeAnswerValidator.Validate(data,data.initial,q.nodeIds[i],null,out _);test(ArchiveTopicQuestions.Validate(q,pick,out _)==expected,key+" preserves every valid alternative node choice "+q.nodeIds[i]);}
                if(ArchiveTreeRules.NumberQuestion(q)){test(good.flags>=0&&good.flags<=5,key+" uses the original numeric range 0 through 5");var wrong=ArchiveTopicChecks.Solution(q);wrong.flags=(good.flags+1)%6;test(!ArchiveTopicQuestions.Validate(q,wrong,out _),key+" rejects the wrong edge count");}
                if(data.type==TreeChallengeType.Spanning)for(int mask=0;mask<(1<<data.initial.Count);mask++){var edges=data.initial.Where((e,i)=>(mask&(1<<i))!=0).ToList();var s=new ArchiveStationState{phase=1,links=edges.Select(e=>ArchiveTreeRules.Encode(q,e)).ToList()};bool expected=TreeAnswerValidator.Validate(data,edges,null,null,out _);bool actual=ArchiveTopicQuestions.Validate(q,s,out _);test(actual==expected,key+" spanning edge subset "+mask+" agrees with the original validator");if(actual)spanningAnswers++;}
            }
            var fixture=ArchiveTopicQuestions.Build(c,9,1,314159);var empty=new ArchiveStationState{phase=1};ArchiveTopicQuestions.Prepare(fixture,empty);test(!ArchiveTreeRules.CanEdit(fixture,empty,-1,0,false,out _),"Incomplete pick cannot edit");var actor=new ArchiveActor{actor=3,treeFirst=2,treeSecond=4,treeRound=1};var restored=JsonUtility.FromJson<ArchiveActor>(JsonUtility.ToJson(actor));test(restored.treeFirst==2&&restored.treeSecond==4&&restored.treeRound==1,"Actor-specific endpoint pick survives the existing checkpoint format");
            }catch(Exception e){r.errors.Add(e.ToString());}r.passed=r.errors.Count==0&&r.checks.All(v=>v.passed);Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T10TreeVariants.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{r.passed,sourceVariants=count,validSpanningAnswers=spanningAnswers,r.checks,r.errors},Newtonsoft.Json.Formatting.Indented));return(r.passed?"Passed":"Failed")+": "+count+" source variants / "+r.checks.Count+" checks / "+spanningAnswers+" valid spanning answers";
        }
        public static void Begin(){if(!Application.isPlaying||Photon.Pun.PhotonNetwork.InRoom||active)throw new InvalidOperationException("Use offline Play Mode.");session=ArchiveTopicSession.Current;station=session.stations[9];ui=ArchiveTopicUI.Current.GetComponent<ArchiveTreeUI>();report=new Report();oldHunting=session.hunting.enabled;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);session.hunting.enabled=false;stack.Clear();stack.Push(Flow());active=true;next=0;Status="Starting";EditorApplication.update+=Tick;Application.logMessageReceived+=Log;}
        static void Log(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)report.errors.Add(message);}
        static void Tick(){if(!active)return;try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup<next)return;if(!Application.isPlaying)throw new Exception("Play stopped.");if(stack.Count==0){Finish(true);return;}var flow=stack.Peek();if(!flow.MoveNext()){stack.Pop();return;}if(flow.Current is IEnumerator nested)stack.Push(nested);else next=EditorApplication.timeSinceStartup+(flow.Current is float delay?delay:0);}catch(Exception ex){report.errors.Add(Status+": "+ex);Finish(false);}}
        static void Move(Vector3 p)=>ArchiveTopicPlayChecks.MoveTo(station,p);
        static IEnumerator Book(){Move(ArchiveTopicStation.BookPosition+Vector3.back*1.7f);station.points.First(p=>p.role==ArchivePointRole.Book).Interact();yield return .18f;}
        static IEnumerator Pick(int i,bool hand=false){if(hand){Move(ArchiveTreeRules.Node(session.Question(9),i));station.points.First(p=>p.role==ArchivePointRole.Node&&p.index==i).Interact();}else ui.NodeButtons[i].onClick.Invoke();yield return .08f;}
        static IEnumerator Edge(int link,bool removing){yield return Pick(link/100);yield return Pick(link%100);Check((removing?ui.RemoveButton:ui.ConnectButton).interactable,"Selected endpoint pair enables "+(removing?"Remove":"Connect"));(removing?ui.RemoveButton:ui.ConnectButton).onClick.Invoke();yield return .12f;Check(session.TreeSelection(session.LocalActor).treeFirst<0&&session.TreeSelection(session.LocalActor).treeSecond<0,"Accepted branch edit clears only the submitting actor's pick");}
        static IEnumerator Arrange(){var good=ArchiveTopicChecks.Solution(session.Question(9));foreach(int link in State.links.Except(good.links).ToArray())yield return Edge(link,true);foreach(int link in good.links.Except(State.links).ToArray())yield return Edge(link,false);}
        static IEnumerator Flow(){session.Initialize(314159);ArchiveTopicUI.Current.Close();yield return .3f;Check(!State.timerRunning&&State.timerAttempt==0,"Tree clock waits for actual first Book activation");Status="T10 Book, live diagram and retained answer";yield return Book();var q=session.Question(9);double deadline=State.timerDeadline;Check(State.timerRunning&&State.timerLimit==600&&session.ActiveTopic==9&&session.treeIncorrectPenaltySeconds==10,"Book starts the source ten-minute tree clock and reserves T10");Check(ui.IsOpen&&session.CanAct(session.LocalActor)&&Time.timeScale==1&&State.timerDeadline==deadline,"Reading the editable tree keeps movement, world and shared clock running");var map=ui.GetComponentInChildren<ArchiveTreeMapGraphic>();Check(map!=null&&map.canvasRenderer.GetMesh()!=null&&map.canvasRenderer.GetMesh().vertexCount>0,"Branch diagram has a rendered UI mesh");Check(ui.NodeButtons.Count(b=>b.gameObject.activeInHierarchy)==q.nodes.Length&&ui.NodeButtons.All(b=>b.GetComponent<UnityEngine.UI.Image>().sprite!=null),"Diagram contains all readable source node buttons with assigned circle art");var good=ArchiveTopicChecks.Solution(q);int wrong=Enumerable.Range(0,q.nodeIds.Length).First(i=>{var s=ArchiveTopicChecks.Solution(q);s.selection=i;return !ArchiveTopicQuestions.Validate(q,s,out _);});yield return Pick(wrong,true);Check(State.selection==wrong,"Hand / E at a world node selects the same shared identification answer");ui.CheckButton.onClick.Invoke();yield return .15f;Check(State.round==0&&State.selection==wrong&&session.State.mistakes.Count==1&&Math.Abs(State.timerDeadline-(deadline-10))<.000001,"Incorrect identification keeps its pick and costs exactly one mistake and ten seconds");State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .2f;Check(State.timerExpired&&State.selection==wrong&&session.State.mistakes.Count==2,"Natural timeout preserves the current answer and adds one timeout mistake");yield return Book();Check(State.selection==wrong&&session.TimerRemaining(State)>598,"Book retry retains the identification variant and selection");yield return Pick(good.selection);yield return 1.6f;ui.CheckButton.onClick.Invoke();yield return .2f;Check(State.round==1&&State.phase==0&&!State.timerRunning,"Identification completes and pauses the remaining clock at the Book");float remaining=session.TimerRemaining(State);yield return .2f;Check(session.TimerRemaining(State)==remaining,"The solved Book gate keeps the exact remaining time");session.Request(8,ArchiveAction.Start);Check(session.State.stations[8].timerAttempt==0&&session.ActiveTopic==9,"Another topic cannot start while Trees is unfinished");
            Status="T10 build rules, pending pick and capture restriction";yield return Book();q=session.Question(9);Check(session.TimerRemaining(State)<=remaining&&session.TimerRemaining(State)>remaining-2,"Next Book resumes the same remaining countdown");yield return Pick(0);ui.ClearButton.onClick.Invoke();yield return .1f;Check(session.TreeSelection(session.LocalActor).treeFirst<0&&State.links.Count==0,"Clear Pick leaves the current tree intact");int root=Array.IndexOf(q.nodeIds,q.tree.root);yield return Pick((root+1)%q.nodes.Length);yield return Pick(root);int revision=session.State.revision;ui.ConnectButton.onClick.Invoke();Check(session.State.revision==revision&&State.links.Count==0,"Authority rejects an incoming root branch without charging a mistake");ui.ClearButton.onClick.Invoke();yield return Pick(0);restriction=new GameObject("T10_Capture_Restriction_Fixture");Player.LocalInstance.AcquireMovementLock(restriction,"T10 capture restriction fixture",Player.LocalInstance.transform.position,session.LocalActor);yield return .2f;Check(!session.CanAct(session.LocalActor)&&session.TreeSelection(session.LocalActor)==null&&!ui.IsOpen,"Movement/capture restriction clears a pending pick and closes tree controls");revision=session.State.revision;session.Request(9,ArchiveAction.Select,1);Check(session.State.revision==revision,"Restricted player cannot edit through the command API");Player.LocalInstance.ReleaseMovementLock(restriction);UnityEngine.Object.Destroy(restriction);restriction=null;ArchiveTopicUI.Current.Open(station);yield return .12f;yield return Arrange();Check(ArchiveTopicQuestions.Validate(q,State,out _),"Native Connect controls build the required rooted tree");ui.CheckButton.onClick.Invoke();yield return .2f;Check(State.round==2&&State.phase==0,"Construction completes through the shared validator");
            Status="T10 repair and source edit guards";yield return Book();q=session.Question(9);good=ArchiveTopicChecks.Solution(q);var bad=State.links.Except(good.links).Single();var missing=good.links.Except(State.links).Single();yield return Pick(missing/100);yield return Pick(missing%100);revision=session.State.revision;ui.ConnectButton.onClick.Invoke();Check(session.State.revision==revision&&!State.links.Contains(missing),"Repair requires removing the existing parent before adding its replacement");ui.ClearButton.onClick.Invoke();yield return Pick(bad%100);yield return Pick(bad/100);ui.RemoveButton.onClick.Invoke();yield return .12f;Check(!State.links.Contains(bad),"Remove accepts reversed endpoint selection for a directed branch");yield return Edge(missing,false);ui.CheckButton.onClick.Invoke();yield return .2f;Check(State.round==3&&State.phase==0,"Repair keeps every other original branch and completes");
            Status="T10 numeric depth and penalty exhaustion";yield return Book();q=session.Question(9);good=ArchiveTopicChecks.Solution(q);Check(ui.NumberButtons.All(b=>b.gameObject.activeInHierarchy&&b.interactable),"Depth exposes all original number choices 0 through 5");wrong=(good.flags+1)%6;ui.NumberButtons[wrong].onClick.Invoke();yield return .1f;int mistakes=session.State.mistakes.Count;State.timerDeadline=ArchiveTopicSession.TimerClock+5.001;ui.CheckButton.onClick.Invoke();yield return .2f;Check(State.timerExpired&&State.flags==wrong&&session.State.mistakes.Count==mistakes+1,"An exhausting wrong-answer penalty adds no second timeout mistake and keeps the number");yield return Book();ui.NumberButtons[good.flags].onClick.Invoke();yield return 1.6f;ui.CheckButton.onClick.Invoke();yield return .2f;Check(State.round==4&&State.phase==0,"Depth uses the original root-at-zero edge count");
            Status="T10 spanning tree and completion";yield return Book();q=session.Question(9);yield return Arrange();Check(State.links.Count==q.nodes.Length-1&&ArchiveTopicQuestions.Validate(q,State,out _),"Spanning tree keeps all source vertices connected without a cycle");ui.CheckButton.onClick.Invoke();yield return .2f;Check(State.phase==2&&State.round==5&&!State.timerRunning&&session.ActiveTopic==-1,"All five Trees challenges complete and release the team topic lock");Check(session.State.stations.Where(s=>s.topic!=9).All(s=>s.round==0&&s.timerAttempt==0),"Trees leaves the other nine topic states and clocks unchanged");
            Status="T10 visual and navigation-safe assets";var art=station.GetComponent<ArchiveTreePresentation>();Check(art.NodeRoots.Length==q.nodes.Length&&art.BranchCount==State.links.Count,"Visible tree matches the actual accepted node/edge state");Check(art.GetComponentsInChildren<Collider>().Length==1,"Tree props retain only the existing Book collider");Check(art.NodeRoots.All(n=>n.Find("Node_Inlay").GetComponent<Renderer>().bounds.min.y>n.Find("Anchor_Stone").GetComponent<Renderer>().bounds.max.y),"Rune rings remain visibly above the stone mesh");Check(art.selectSound!=null&&art.connectSound!=null&&art.correctSound!=null&&art.incorrectSound!=null&&art.sparkMesh!=null&&art.sparkMaterial!=null,"Selection, branch, verdict sound and capped mesh feedback assets are assigned");ArchiveTopicUI.Current.Close();Move(Vector3.zero);yield return .15f;var position=ui.Objective.anchoredPosition;var size=ui.Objective.sizeDelta;var camera=Camera.main;var rotation=camera.transform.rotation;for(int i=0;i<12;i++){camera.transform.rotation=Quaternion.Euler(15,i*30,0);yield return .04f;Check(ui.IsObjectiveVisible&&ui.Objective.anchoredPosition==position&&ui.Objective.sizeDelta==size,"Compact tree controls stay fixed at camera angle "+i);}camera.transform.rotation=rotation;
        }
        static void Finish(bool ok){active=false;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;stack.Clear();if(restriction!=null){Player.LocalInstance.ReleaseMovementLock(restriction);UnityEngine.Object.Destroy(restriction);}if(session!=null&&Application.isPlaying){session.hunting.enabled=oldHunting;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);ArchiveTopicUI.Current.Close();}report.passed=ok&&report.errors.Count==0&&report.checks.All(c=>c.passed);Status=report.passed?"Passed":"Failed";Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T10PolishPlayMode.json",JsonUtility.ToJson(report,true));Debug.Log("T10 Tree of Connections: "+Status+" / "+report.checks.Count);}
    }
}
